from pathlib import Path
p=Path('dict.c')
s=p.read_text(encoding='utf-8', errors='replace')

# Patch xmlDictAddString: replace the 'if (size / 4 < namelen) { ... size = 4 * (size_t) namelen; ... }' block
old = """        if (size / 4 < namelen) {
            if ((size_t) namelen + 0 < (SIZE_MAX - sizeof(xmlDictStrings)) / 4)
                size = 4 * (size_t) namelen; /* just in case ! */
            else
                return(NULL);
        }
"""
if old not in s:
    raise SystemExit('expected xmlDictAddString sizing block not found')
new = """        /*
         * Ensure the pool is large enough for very long names without
         * over-allocating (important for tight memory limits).
         */
        {
            size_t need = (size_t) namelen + 1; /* include NUL */
            if (need > size) {
                if (need <= (SIZE_MAX - sizeof(xmlDictStrings)) / 2)
                    size = 2 * need;
                else if (need <= SIZE_MAX - sizeof(xmlDictStrings))
                    size = need;
                else
                    return(NULL);
            }
        }
"""
s = s.replace(old, new)

# Patch xmlDictAddQString: replace the 'if (size < 4 * (namelen + plen + 1)) size = 4 * ...' line.
old2 = """        if (size < 4 * (namelen + plen + 1))
	    size = 4 * (namelen + plen + 1); /* just in case ! */
"""
if old2 not in s:
    raise SystemExit('expected xmlDictAddQString sizing block not found')
new2 = """        /*
         * Ensure the pool is large enough for very long QNames without
         * excessive over-allocation.
         */
        {
            size_t need = (size_t) namelen + (size_t) plen + 2; /* ':' + NUL */
            if (need > size) {
                if (need <= (SIZE_MAX - sizeof(xmlDictStrings)) / 2)
                    size = 2 * need;
                else if (need <= SIZE_MAX - sizeof(xmlDictStrings))
                    size = need;
                else
                    return(NULL);
            }
        }
"""
s = s.replace(old2, new2)

p.write_text(s, encoding='utf-8')
print('patched dict.c')
PY
